yakit.AutoInitYakit()

status = (i) => {
    yakit.StatusCard("状态", i)
}

// 提取URL路径的目录部分
func extractUrlPathDir(url) {
    // 移除查询参数和片段
    baseUrl = str.Split(url, "?")[0]
    baseUrl = str.Split(baseUrl, "#")[0]

    // 按"/"分割路径
    parts = str.Split(baseUrl, "/")

    // 重建到目录层级的路径（排除最后一个元素）
    if len(parts) > 0 {
        // 组合协议、域名和路径（排除最后一部分）
        resultParts = parts[:len(parts)-1]
        return str.Join(resultParts, "/") + "/"
    }
    return url + "/"  // 如果无法分割，直接返回
}

handle = func(origin /* string */) {
    if str.ParseStringToPorts(origin).Len() <= 0 {
        status("输入不合法：%v" % origin)
        return ""
    }


    buf = bufio.NewBuffer()

    filter = str.NewFilter()
    count := 0
    go func {
        for {
            if count > 0 {
                yakit.StatusCard("进度", "已检查%v条流量" % count)
            }
            println("checking process")
            time.Sleep(1)
        }

    }

    for i in str.ParseStringToPorts(origin) {
        for result in db.QueryHTTPFlowsByID(i) {
            host := str.ExtractHost(result.Url)
            for kw in ["https://" + host, "http://" + host] {
                for flow in yakit.QueryHTTPFlowsByKeyword(kw) {
                    if !str.HasPrefix(flow.Url, kw) {
                        continue
                    }

                    // 提取URL路径的目录部分
                    urlPath = extractUrlPathDir(flow.Url)

                    if filter.Exist(urlPath) {
                        continue
                    }

                    count++
                    filter.Insert(urlPath)
                    buf.Write(urlPath + "\n")
                }

            }

        }

    }


    return buf.String()
}
